/* @autogenerated */
package net.civeira.phylax.common.value.importation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.Optional;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import net.civeira.phylax.common.value.validation.ConstraintFailList;

@DisplayName("NumericLoad")
class NumericLoadUnitTest {

  @Nested
  @DisplayName("Localized decimal parsing")
  class Parsing {

    @ParameterizedTest(name = "\"{0}\" -> {1}")
    @CsvSource(delimiter = ';',
        value = {"1234; 1234", "-12.5; -12.5", "1.23E3; 1.23E+3", "1,234.56; 1234.56",
            "1.234,56; 1234.56", "1234,56; 1234.56", "' 1 234,56 '; 1234.56", "1'234.56; 1234.56",
            "1.234.567; 1234.567", "1,234,567; 1234.567", "+7; 7", "1'234; 1234"})
    @DisplayName("Should accept US, EU, Swiss and scientific notations")
    void shouldParseLocalizedNumbers(String value, String expected) {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(new BigDecimal(expected)),
          NumericLoad.toBigDecimal("amount", value, fails));
      assertTrue(fails.isEmpty());
    }

    @ParameterizedTest(name = "\"{0}\"")
    @NullAndEmptySource
    @ValueSource(strings = {"  "})
    @DisplayName("Should report missing values as NOT_NULL")
    void shouldReportMissingValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(NumericLoad.toBigDecimal("amount", value, fails).isEmpty());
      assertTrue(fails.includeCode("NOT_NULL"));
    }

    @ParameterizedTest(name = "\"{0}\"")
    @ValueSource(strings = {"abc", "1.2,x", "x.5", "1,x"})
    @DisplayName("Should report unparseable values with the type specific code")
    void shouldReportInvalidValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(NumericLoad.toBigDecimal("amount", value, fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_NUMERIC"));
    }
  }

  @Nested
  @DisplayName("Typed conversions")
  class Typed {

    @Test
    @DisplayName("Should convert to int and reject decimals, overflow and garbage")
    void shouldConvertToInt() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(42), NumericLoad.toInt("n", "42", fails));
      assertTrue(NumericLoad.toInt("n", "1.5", fails).isEmpty());
      assertTrue(NumericLoad.toInt("n", "3000000000", fails).isEmpty());
      assertTrue(fails.includeCode("OUT_OF_RANGE_INTEGER"));
      assertTrue(NumericLoad.toInt("n", "x", fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_INTEGER"));
    }

    @Test
    @DisplayName("Should convert to long and reject overflow and garbage")
    void shouldConvertToLong() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(3000000000L), NumericLoad.toLong("n", "3000000000", fails));
      assertTrue(NumericLoad.toLong("n", "1E30", fails).isEmpty());
      assertTrue(fails.includeCode("OUT_OF_RANGE_LONG"));
      assertTrue(NumericLoad.toLong("n", "x", fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_LONG"));
    }

    @Test
    @DisplayName("Should convert to double and reject infinite values and garbage")
    void shouldConvertToDouble() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(1.5d), NumericLoad.toDouble("n", "1,5", fails));
      assertTrue(NumericLoad.toDouble("n", "1E400", fails).isEmpty());
      assertTrue(fails.includeCode("OUT_OF_RANGE_DOUBLE"));
      assertTrue(NumericLoad.toDouble("n", "x", fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_DOUBLE"));
    }

    @Test
    @DisplayName("Should convert to float and reject infinite values and garbage")
    void shouldConvertToFloat() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(2.25f), NumericLoad.toFloat("n", "2.25", fails));
      assertTrue(NumericLoad.toFloat("n", "1E50", fails).isEmpty());
      assertTrue(fails.includeCode("OUT_OF_RANGE_FLOAT"));
      assertTrue(NumericLoad.toFloat("n", "x", fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_FLOAT"));
    }

    @Test
    @DisplayName("Should convert to BigInteger and reject decimals and garbage")
    void shouldConvertToBigInteger() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(new BigInteger("123456789012345678901234567890")),
          NumericLoad.toBigInteger("n", "123456789012345678901234567890", fails));
      assertTrue(NumericLoad.toBigInteger("n", "1.5", fails).isEmpty());
      assertTrue(fails.includeCode("OUT_OF_RANGE_INTEGER"));
      assertTrue(NumericLoad.toBigInteger("n", "x", fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_INTEGER"));
    }
  }
}
